      const fs = await import(/* @vite-ignore */ 'fs');
      const path = await import(/* @vite-ignore */ 'path');
      const filePath = path.join(process.cwd(), 'docs', 'POSTMORTEMS.md');
      if (fs.existsSync(filePath)) {
